/**
 * Core glyph transformation function.
 *
 * Takes glyph bounds and text parameters, computes:
 * 1. Clipped glyph position in local space
 * 2. Atlas UV coordinates for SDF lookup
 * 3. Glyph dimensions and texture channel
 *
 * Sets up varyings for fragment shader compatibility:
 * - vTextPacked0: vec4(textUV.xy, glyphUV.xy)
 * - vTextPacked1: vec4(glyphDims.xy, texChannel, letterId)
 * - vTextTextureUVBounds: vec4(atlasStart.xy, atlasEnd.xy)
 * - vTextWordId: float (word/member index)
 *
 * @tsl
 * @param {Object} params - Transformation parameters
 * @param {ShaderNode} params.glyphBounds - vec4(minX, minY, maxX, maxY) glyph bounds
 * @param {ShaderNode} params.atlasIndex - float atlas glyph index
 * @param {ShaderNode} params.letterId - float letter index within text
 * @param {ShaderNode} params.wordId - float word/member index (0 for single Text)
 * @param {ShaderNode} params.clipRect - vec4(minX, minY, maxX, maxY) clip rectangle
 * @param {ShaderNode} params.posOffset - vec2(offsetX, offsetY) position offset
 * @param {ShaderNode} params.distanceOffset - float SDF distance offset (outline)
 * @param {ShaderNode} params.blurRadius - float SDF blur radius
 * @param {ShaderNode} params.totalBounds - vec4(minX, minY, maxX, maxY) text block bounds
 * @param {ShaderNode} params.sdfTextureSize - vec2(width, height) SDF atlas size
 * @param {ShaderNode} params.sdfGlyphSize - float glyph tile size in atlas
 * @returns {Fn} TSL function that returns the transformed position (vec3)
 *
 * @tags WebGPU, WebGL
 * @category Text
 * @private
 */
export function textGlyphTransform({ glyphBounds, atlasIndex, letterId, wordId, clipRect, posOffset, distanceOffset, blurRadius, totalBounds, sdfTextureSize, sdfGlyphSize, }: {
    glyphBounds: ShaderNode;
    atlasIndex: ShaderNode;
    letterId: ShaderNode;
    wordId: ShaderNode;
    clipRect: ShaderNode;
    posOffset: ShaderNode;
    distanceOffset: ShaderNode;
    blurRadius: ShaderNode;
    totalBounds: ShaderNode;
    sdfTextureSize: ShaderNode;
    sdfGlyphSize: ShaderNode;
}): Fn;
